def emi(P, r, n):
    if r == 0:
        return round(P / n, 2)
    i = r / 100 / 12
    numerator = i * (1 + i) ** n
    denominator = (1 + i) ** n - 1
    emi = round(numerator / denominator * P, 2)
    return emi

